import { Stat } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof Stat>,
    'label' | 'value' | 'unit' | 'description'
  > = {
    label: 'Rate limit',
    value: '60',
    unit: 'req/min',
    description: 'per API key; 429 is returned once exceeded.',
  };
  return <Stat {...args} />;
}

import { Stat } from '@refy-design/web';
import { StatGroup } from '@refy-design/web';
export function Example() {
  return (
    <StatGroup style={{ maxWidth: 560 }}>
      <Stat
        label="Analyses this cycle"
        value="128"
        delta={{ value: '+12%', trend: 'up' }}
        description="vs previous cycle"
      />
      <Stat
        label="Average progress"
        value="74"
        delta={{ value: '-3 pts', trend: 'down' }}
        description="vs previous cycle"
      />
      <Stat
        label="Cost per analysis"
        value="18"
        unit="credits"
        delta={{ value: '+2', trend: 'up', sentiment: 'negative' }}
        description="going up is bad here, inverted sentiment"
      />
    </StatGroup>
  );
}

import { Sparkline } from '@refy-design/web';
import { Stat } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof Stat>,
    'label' | 'value' | 'delta' | 'chart'
  > = {
    label: 'Analyses / day',
    value: '42',
    delta: { value: '+8%', trend: 'up' },
    chart: (
      <Sparkline
        data={[12, 18, 14, 22, 26, 24, 31, 29, 38, 42]}
        label="Analyses per day trend"
      />
    ),
  };
  return <Stat {...args} />;
}
